<?php require '../includes/config.php'; require '../includes/layout.php';$ticket=null;if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$ref=strtoupper(trim($_POST['ref_number']));$stmt=$conn->prepare('SELECT t.*,d.name department_name,u.full_name FROM tickets t LEFT JOIN departments d ON d.id=t.department_id JOIN users u ON u.id=t.student_id WHERE t.ref_number=? LIMIT 1');$stmt->bind_param('s',$ref);$stmt->execute();$ticket=$stmt->get_result()->fetch_assoc();if(!$ticket)$error='No complaint was found for this reference number.';}public_head('Track Complaint');?><section class="auth-page"><div class="auth-box card-panel"><h2>Track a Complaint</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="label">Complaint Reference Number</label><input name="ref_number" placeholder="FWCM-2026-XXXXXX" required><button class="btn btn-primary" style="width:100%">Check Status</button></form><?php if(!empty($error))echo'<div class="alert alert-error">'.e($error).'</div>';if($ticket){echo'<div class="tracking-result" style="margin-top:18px;padding:12px;background:#f7faf8"><h3>'.e($ticket['ref_number']).'</h3><p><b>Status:</b> <span class="badge">'.e($ticket['status']).'</span></p><p><b>Subject:</b> '.e($ticket['subject']).'</p><p><b>Assigned Department:</b> '.e($ticket['department_name']?:'Pending administration routing').'</p><p><b>Submitted:</b> '.e(date('d M Y, H:i',strtotime($ticket['created_at']))).'</p>';if($ticket['resolution'])echo'<p><b>Resolution:</b> '.e($ticket['resolution']).'</p>';echo'</div>'; }?></div></section><?php public_footer(); ?>